checks AS (
 SELECT p.photo->>'path' AS path,p.photo->>'proposed_action' AS proposed_action,
 o.id IS NOT NULL AS object_exists,
 o.id=(p.photo->>'id')::uuid AND o.created_at=(p.photo->>'database_created_at')::timestamptz AND o.owner_id IS NOT DISTINCT FROM p.photo->>'owner_id' AS identity_matches,
 coalesce((SELECT jsonb_agg(l.id ORDER BY l.id) FROM public.listings l WHERE l.photo_path=p.photo->>'path'),'[]'::jsonb) AS listing_references
 FROM expected p LEFT JOIN storage.objects o ON o.bucket_id='food-photos' AND o.name=p.photo->>'path'
)
SELECT jsonb_build_object(
 'checked_at',now(),
 'food_photo_count',(SELECT count(*) FROM storage.objects WHERE bucket_id='food-photos'),
 'remaining_candidate_objects',(SELECT count(*) FROM checks WHERE proposed_action LIKE 'candidate-delete%' AND object_exists),
 'candidate_reference_count',(SELECT coalesce(sum(jsonb_array_length(listing_references)),0) FROM checks WHERE proposed_action LIKE 'candidate-delete%'),
 'preserved_objects_verified',(SELECT count(*) FROM checks WHERE proposed_action='preserve' AND object_exists AND identity_matches),
 'photo_checks',(SELECT jsonb_agg(to_jsonb(c) ORDER BY path) FROM checks c)
) AS demo17_storage_report;
